mapper.sql:
FROM USERS u LEFT JOIN ( SELECT user_idx, COUNT(*) AS social_count, GROUP_CONCAT(provider ORDER BY provider) AS linked_providers FROM USER_SOCIAL GROUP BY user_idx ) s ON u.user_idx = s.user_idx LEFT JOIN ( SELECT user_idx, MAX(login_at) AS last_login_at, SUBSTRING_INDEX( GROUP_CONCAT(login_method ORDER BY login_at DESC), ',', 1 ) AS last_login_method, SUM(CASE WHEN is_success = 1 THEN 1 ELSE 0 END) AS login_success_count, SUM(CASE WHEN is_success = 0 THEN 1 ELSE 0 END) AS login_fail_count FROM USER_LOGIN_HISTORY GROUP BY user_idx ) h ON u.user_idx = h.user_idx
AND u.account_status = #{status}
AND u.user_role = #{role}
AND s.user_idx IS NULL
AND FIND_IN_SET(#{provider}, IFNULL(s.linked_providers, '')) > 0
AND DATE(u.created_at) >= #{dateFrom}
AND DATE(u.created_at) <= #{dateTo}
AND u.user_id LIKE CONCAT('%', #{keyword}, '%')
AND u.nickname LIKE CONCAT('%', #{keyword}, '%')
AND u.user_email LIKE CONCAT('%', #{keyword}, '%')
AND (u.user_id LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.user_email LIKE CONCAT('%', #{keyword}, '%'))

mapper.select:
SELECT * FROM USER_LOGIN_HISTORY
WHERE user_idx = #{userIdx}
ORDER BY login_at DESC
LIMIT #{limit}
